const express = require('express');
const crypto = require('crypto');
const nodemailer = require('nodemailer');

const app = express();
app.use(express.json());

// Feature flag cache with TTL
const flagCache = new Map();
const FLAG_TTL = 300000; // 5 minutes

// Email template cache
const templateCache = new Map();

class FeatureFlagService {
  constructor() {
    this.flags = new Map([
      ['email_html_enabled', { value: true, scope: 'global' }],
      ['email_tracking_pixel', { value: false, scope: 'global' }],
      ['custom_sender_name', { value: false, scope: 'tenant' }],
    ]);
  }

  getFlag(flagName, context) {
    const cacheKey = this._buildCacheKey(flagName, context);
    const cached = flagCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < FLAG_TTL) {
      return cached.value;
    }
    const flag = this.flags.get(flagName);
    if (!flag) return null;
    const resolved = this._resolveFlag(flag, context);
    flagCache.set(cacheKey, { value: resolved, timestamp: Date.now() });
    return resolved;
  }

  _buildCacheKey(flagName, context) {
    const contextStr = context.tenantId || 'global';
    return `${flagName}:${contextStr}`;
  }

  _resolveFlag(flag, context) {
    if (flag.scope === 'tenant' && context.tenantId) {
      return context.overrides?.[flag] ?? flag.value;
    }
    return flag.value;
  }
}

class EmailTemplateEngine {
  constructor(flagService) {
    this.flagService = flagService;
  }

  buildTemplate(templateId, context, variables) {
    const cacheKey = this._templateCacheKey(templateId, context);
    const cached = templateCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < FLAG_TTL) {
      return this._interpolate(cached.template, variables);
    }

    let template = this._loadBaseTemplate(templateId);
    const htmlEnabled = this.flagService.getFlag('email_html_enabled', context);
    const trackingEnabled = this.flagService.getFlag('email_tracking_pixel', context);

    if (htmlEnabled) {
      template = this._wrapHtml(template);
    }
    if (trackingEnabled) {
      template = this._addTracking(template, context);
    }

    templateCache.set(cacheKey, { template, timestamp: Date.now() });
    return this._interpolate(template, variables);
  }

  _templateCacheKey(templateId, context) {
    return `tmpl:${templateId}:${context.tenantId || 'default'}`;
  }

  _loadBaseTemplate(templateId) {
    const templates = {
      'welcome': 'Welcome {{name}}! Your account is ready.',
      'reset': 'Hi {{name}}, click here to reset: {{resetLink}}',
      'invoice': 'Invoice #{{invoiceId}} for {{amount}} - {{details}}',
    };
    return templates[templateId] || 'Hello {{name}}';
  }

  _wrapHtml(template) {
    return `<html><body><div class="content">${template}</div></body></html>`;
  }

  _addTracking(template, context) {
    const pixel = `<img src="https://track.example.com/pixel?t=${context.tenantId}" width="1" height="1" />`;
    return template.replace('</body>', `${pixel}</body>`);
  }

  _interpolate(template, variables) {
    let result = template;
    for (const [key, value] of Object.entries(variables)) {
      const sanitized = this._sanitizeValue(value, template);
      result = result.replace(new RegExp(`{{${key}}}`, 'g'), sanitized);
    }
    return result;
  }

  _sanitizeValue(value, template) {
    if (typeof value !== 'string') return String(value);
    if (!template.includes('<html>')) {
      return value;
    }
    return value.replace(/[<>"'&]/g, (c) => ({
      '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '&': '&amp;'
    })[c]);
  }
}

class EmailService {
  constructor() {
    this.flagService = new FeatureFlagService();
    this.templateEngine = new EmailTemplateEngine(this.flagService);
    this.transporter = nodemailer.createTransport({
      host: process.env.SMTP_HOST || 'localhost',
      port: parseInt(process.env.SMTP_PORT || '587'),
      secure: true,
      auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
      },
    });
  }

  async sendEmail(req) {
    const { to, templateId, variables, tenantId } = req.body;
    if (!to || !templateId) {
      throw new Error('Missing required fields');
    }
    if (!this._validateEmail(to)) {
      throw new Error('Invalid email address');
    }

    const context = { tenantId: tenantId || 'default', overrides: req.body.overrides };
    const body = this.templateEngine.buildTemplate(templateId, context, variables || {});
    const isHtml = body.includes('<html>');

    const mailOptions = {
      from: process.env.SENDER_EMAIL || 'noreply@example.com',
      to,
      subject: variables?.subject || 'Notification',
      [isHtml ? 'html' : 'text']: body,
    };

    return this.transporter.sendMail(mailOptions);
  }

  _validateEmail(email) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email) && email.length < 255;
  }
}

const emailService = new EmailService();

app.post('/api/send', async (req, res) => {
  try {
    await emailService.sendEmail(req);
    res.json({ success: true });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.post('/api/flags/update', (req, res) => {
  const { flagName, value, scope } = req.body;
  const apiKey = req.headers['x-api-key'];
  if (apiKey !== process.env.ADMIN_API_KEY) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  emailService.flagService.flags.set(flagName, { value, scope: scope || 'global' });
  flagCache.clear();
  templateCache.clear();
  res.json({ success: true });
});

app.listen(3000, () => console.log('Email service running on port 3000'));

module.exports = { EmailService, FeatureFlagService, EmailTemplateEngine };
